function readStore(key,fallback){try {const v=localStorage.getItem(key);return v===null?fallback:JSON.parse(v)}catch{return fallback}}
function writeStore(key,val){try{localStorage.setItem(key,JSON.stringify(val))}catch{}}
function countCart(){return Object.values(cart).reduce((sum,q)=>sum+q,0)}
function updateCount(){const e=document.getElementById('navCount');if(e)e.textContent=countCart()}
function cartTotal(){return Object.entries(cart).reduce((s,[id,q])=>s+(productById(id)?.price||0)*q,0)}
function addCart(id){cart[id]=(cart[id]||0)+1;writeStore('kalantzis_cart',cart);updateCount();toast(t('Προστέθηκε στο καλάθι','Added to cart'));}
function toast(message,isError=false){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className=`toast ${isError?'error':''}`;el.setAttribute('role','status');el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),3600)}
